import json
import os
import pathlib

from azure.ai.contentunderstanding import ContentUnderstandingClient
from azure.ai.contentunderstanding.models import ArrayField, ObjectField
from azure.core.credentials import AzureKeyCredential

UMBRAL = 0.80
EXTENSIONES = {".pdf", ".jpg", ".jpeg", ".png", ".tiff"}

client = ContentUnderstandingClient(
    endpoint=os.environ["CONTENTUNDERSTANDING_ENDPOINT"],
    credential=AzureKeyCredential(os.environ["CONTENTUNDERSTANDING_KEY"]),
)
analyzer_id = os.getenv("CU_ANALYZER_ID", "prebuilt-invoice")


def simplificar(campo):
    """Devuelve valor y confianza, recorriendo objetos y arrays."""
    if campo is None:
        return None
    if isinstance(campo, ObjectField):
        return {k: simplificar(v) for k, v in (campo.value or {}).items()}
    if isinstance(campo, ArrayField):
        return [simplificar(v) for v in (campo.value or [])]
    return {"valor": campo.value, "confianza": campo.confidence}


def confianzas(nodo):
    """Lista plana de confianzas presentes en el resumen."""
    if isinstance(nodo, dict) and "confianza" in nodo:
        return [nodo["confianza"]] if nodo["confianza"] is not None else []
    if isinstance(nodo, dict):
        return [c for v in nodo.values() for c in confianzas(v)]
    if isinstance(nodo, list):
        return [c for v in nodo for c in confianzas(v)]
    return []


entrada = pathlib.Path("entrada")
salida = pathlib.Path("salida")
salida.mkdir(exist_ok=True)
revision = []

for archivo in sorted(entrada.iterdir()):
    if archivo.suffix.lower() not in EXTENSIONES:
        continue
    print(f"Analizando {archivo.name} con {analyzer_id}...")
    try:
        poller = client.begin_analyze_binary(
            analyzer_id=analyzer_id,
            binary_input=archivo.read_bytes(),
        )
        result = poller.result()
    except Exception as err:  # errores de red, cuota o modelo
        print(f"  ERROR: {err}")
        continue

    # JSON completo del servicio
    (salida / f"{archivo.stem}.raw.json").write_text(
        json.dumps(result.as_dict(), indent=2, ensure_ascii=False, default=str),
        encoding="utf-8",
    )

    content = result.contents[0]
    resumen = {n: simplificar(f) for n, f in (content.fields or {}).items()}
    (salida / f"{archivo.stem}.campos.json").write_text(
        json.dumps(resumen, indent=2, ensure_ascii=False, default=str),
        encoding="utf-8",
    )

    minima = min(confianzas(resumen), default=0.0)
    if minima < UMBRAL:
        revision.append({"archivo": archivo.name, "confianza_minima": minima})
    print(f"  OK - {len(resumen)} campos, confianza mínima {minima:.2f}")

(salida / "revision_humana.json").write_text(
    json.dumps(revision, indent=2, ensure_ascii=False), encoding="utf-8"
)
print(f"Documentos para revisión humana: {len(revision)}")
